const invoiceData = $input.first().json.value || [];
const hsResult    = $('Find HubSpot Company').first().json.results?.[0];

if (!hsResult) return [{ json: { error: 'HubSpot company not found for this ERP' } }];

const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const todayMs = today.getTime();

// No invoices → Not Ordered, no threshold dates
if (invoiceData.length === 0) {
  const props = { ordering_status: 'Not Ordered', ordering_status_date_changed: null };
  return [{ json: {
    hsId: hsResult.id,
    customerName: hsResult.properties?.name,
    orderingStatus: 'Not Ordered',
    hsUpdatePayload: props
  } }];
}

const invList = invoiceData; // sorted desc, max 10

// 1. Last invoice date (ms epoch for HubSpot)
const lastInvoiceDateStr = invList[0].invoiceDate;
const lastInvoiceDateMs  = new Date(lastInvoiceDateStr + 'T00:00:00Z').getTime();

// 2. Avg order size
const avgOrderSize = Math.round(
  (invList.reduce((s, i) => s + (Number(i.totalAmountIncludingTax) || 0), 0) / invList.length) * 100
) / 100;

// 3. Avg days between orders
let avgDaysBetweenOrders = null;
const sortedAsc = [...invList].sort((a, b) => new Date(a.invoiceDate) - new Date(b.invoiceDate));
if (sortedAsc.length >= 2) {
  const gaps = [];
  for (let i = 1; i < sortedAsc.length; i++) {
    gaps.push((new Date(sortedAsc[i].invoiceDate) - new Date(sortedAsc[i-1].invoiceDate)) / DAY);
  }
  avgDaysBetweenOrders = Math.round((gaps.reduce((s, g) => s + g, 0) / gaps.length) * 10) / 10;
}

// 4. Risk Day and Lost Day
let riskDayMs, lostDayMs;
if (avgDaysBetweenOrders !== null) {
  // Round to whole days so timestamps always land at midnight UTC (HubSpot requirement)
  const riskDays = Math.max(Math.round(avgDaysBetweenOrders * 2), 5);
  const lostDays = Math.max(Math.round(avgDaysBetweenOrders * 3), 7);
  riskDayMs = lastInvoiceDateMs + riskDays * DAY;
  lostDayMs = lastInvoiceDateMs + lostDays * DAY;
} else {
  riskDayMs = lastInvoiceDateMs + 14 * DAY;
  lostDayMs = lastInvoiceDateMs + 28 * DAY;
}

// 5. Ordering status
let newStatus;
if      (todayMs >= lostDayMs) newStatus = 'Potentially Lost';
else if (todayMs >= riskDayMs) newStatus = 'Outside Ordering Pattern';
else                            newStatus = 'Actively Ordering';

// 6. Status date = when the customer entered this tier (threshold date, not today)
let statusDateMs;
if      (newStatus === 'Potentially Lost')          statusDateMs = lostDayMs;
else if (newStatus === 'Outside Ordering Pattern')  statusDateMs = riskDayMs;
else                                                statusDateMs = lastInvoiceDateMs;

const props = {
  last_invoice_date:              lastInvoiceDateMs,
  avg_order_size:                 avgOrderSize,
  ordering_status:                newStatus,
  ordering_status_date_changed:   statusDateMs
};
if (avgDaysBetweenOrders !== null) props.avg_days_between_orders = avgDaysBetweenOrders;

return [{ json: {
  hsId:                 hsResult.id,
  customerName:         hsResult.properties?.name,
  lastInvoiceDate:      lastInvoiceDateStr,
  avgOrderSize,
  avgDaysBetweenOrders,
  invoiceCount:         invList.length,
  riskDay:              new Date(riskDayMs).toISOString().slice(0, 10),
  lostDay:              new Date(lostDayMs).toISOString().slice(0, 10),
  orderingStatus:       newStatus,
  statusDate:           new Date(statusDateMs).toISOString().slice(0, 10),
  hsUpdatePayload:      props
} }];
